/* Weather Risk Intelligence: chat UI styles. Colours are tokens so dark mode is one block. */
:root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #f0f3f7;
  --border: #dde3ea;
  --text: #17202b;
  --muted: #5d6b7a;
  --accent: #1f5fbf;
  --accent-text: #ffffff;
  --user-bubble: #1f5fbf;
  --user-text: #ffffff;
  --high: #c0392b;
  --elevated: #d9822b;
  --moderate: #c9a227;
  --low: #3b8d5a;
  --warn-bg: #fff4e5;
  --warn-text: #8a4b00;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(16, 24, 40, 0.08);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f141b;
    --surface: #161d26;
    --surface-2: #1d2631;
    --border: #2a3542;
    --text: #e6ebf1;
    --muted: #93a1b0;
    --accent: #5b9bf0;
    --accent-text: #0b1220;
    --user-bubble: #2d5fa3;
    --user-text: #ffffff;
    --warn-bg: #3a2a12;
    --warn-text: #f3c27a;
    --shadow: none;
  }
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-size: 15px;
  line-height: 1.5;
  display: flex;
  flex-direction: column;
}

/* ---------------------------------------------------------------- top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.logo { font-size: 28px; }
