  border-radius: 10px;
  padding: 10px 18px;
  font-weight: 600;
}
.btn-primary:disabled { opacity: 0.5; cursor: wait; }
.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 13px;
}
.btn-icon {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 11px;
  font-size: 16px;
}
.btn-icon.listening { background: var(--high); border-color: var(--high); animation: pulse 1s infinite; }

