.answer-meta { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 8px; }
.badge {
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
}
.badge.conf-high { color: var(--low); border-color: var(--low); }
.badge.conf-medium { color: var(--elevated); border-color: var(--elevated); }
.badge.conf-low { color: var(--high); border-color: var(--high); }

table.result { width: 100%; border-collapse: collapse; margin: 6px 0 10px; font-size: 14px; }
table.result th, table.result td { text-align: left; padding: 5px 8px; border-bottom: 1px solid var(--border); }
table.result th { color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; }
table.result td.num { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }

.figures { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 10px; }
.figure { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 6px 10px; }
.figure .v { font-weight: 700; font-variant-numeric: tabular-nums; }
.figure .l { display: block; font-size: 12px; color: var(--muted); }

details { margin-top: 6px; font-size: 14px; }
details summary { cursor: pointer; color: var(--muted); font-size: 13px; }
details ul { margin: 6px 0 4px; padding-left: 20px; }

.warning {
  background: var(--warn-bg);
  color: var(--warn-text);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 13px;
  margin-top: 8px;
}
.followups { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }

.thinking { color: var(--muted); font-style: italic; }
.thinking::after { content: " ●"; animation: pulse 1s infinite; }
@keyframes pulse { 50% { opacity: 0.2; } }

/* ---------------------------------------------------------------- composer */
.composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  padding: 12px;
  border-top: 1px solid var(--border);
}
.composer textarea {
  flex: 1;
  resize: none;
  max-height: 140px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
  font: inherit;
}
.composer textarea:focus { outline: 2px solid var(--accent); outline-offset: -1px; }

button { font: inherit; cursor: pointer; }
.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
  border: none;
  border-radius: 10px;
  padding: 10px 18px;
  font-weight: 600;
}
.btn-primary:disabled { opacity: 0.5; cursor: wait; }
.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 13px;
}
.btn-icon {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 11px;
  font-size: 16px;
}
.btn-icon.listening { background: var(--high); border-color: var(--high); animation: pulse 1s infinite; }

/* ---------------------------------------------------------------- mobile */
@media (max-width: 820px) {
  .layout { grid-template-columns: 1fr; padding: 10px 16px; }
  .ranking-panel { max-height: 260px; }
  .subtitle, .toggle { display: none; }
  .msg.user { max-width: 90%; }
}

